ProjectALife.DialogueShards["scenes_shelter_2"] = {
{"fw_ld6_shelter_civ_1_0131","shelter",3,"reg=civilian,family,worker,rescue",{1,"Where would your people go if the house wasn't safe?",2,"Aunt Peg's farm, past Rineyville",1,"That's where mine would go too. Same sort of farm",3,"How many aunts have farms around here?"}},
{"fw_ld6_shelter_civ_1_0132","shelter",2,"reg=civilian,family,worker,rescue|mood=sad",{1,"The answering machine, the last message was my mom saying call me back, it's nothing, just call me",2,"Did you?",1,"I was gonna call her Sunday"}},
{"fw_ld6_shelter_civ_1_0133","shelter",3,"reg=civilian,family,worker,rescue|mood=fear",{1,"I keep thinking about my truck sitting in the lot at work",2,"Your truck?",1,"It's just sitting there, getting hot, I don't know why I keep thinking about it",2,"It's a truck, it's fine",1,"I know it's a truck"}},
{"fw_ld6_shelter_civ_1_0134","shelter",4,"reg=civilian,family,worker,rescue|mood=fear",{1,"My mother takes blood pressure pills, twice a day",2,"How many does she have?",1,"That's the thing, I don't know, I never counted",2,"She'll know to stretch them",3,"Mothers always know..."}},
{"fw_ld6_shelter_civ_1_0135","shelter",2,"reg=civilian,family,worker,rescue|mood=sad",{1,"My ex called last Wednesday, left a message, wanted to talk",2,"You call back?",1,"I thought I'd wait till the weekend, make him sweat",2,"Oh, no..."}},
{"fw_ld6_shelter_civ_1_0136","shelter",4,"reg=civilian,family,worker,rescue|mood=fear",{1,"Last I heard, both my kids were with their grandmother in Brandenburg",2,"I remember Brandenburg being quiet",1,"It was quiet, I don't know what it is now",2,"I wish somebody could bring you news. Quiet doesn't tell us enough",3,"No. But I keep listening anyway"}},
{"fw_ld6_shelter_civ_1_0137","shelter",2,"reg=civilian,family,worker,rescue|mood=fear",{1,"I can still smell the hospital on my hands",2,"Wash them",1,"I did, three times, with the little bar of soap",2,"Then it's in your head"}},
{"fw_ld6_shelter_civ_1_0138","shelter",3,"reg=civilian,family,worker,rescue|mood=sad",{1,"My cousin was getting married in two weeks",2,"Oh",1,"I already bought the gift, it's in my trunk, a toaster, a stupid toaster",2,"You could still give it to him",1,"I could give it to him on the other side",3,"A toaster's a good gift"}},
{"fw_ld6_shelter_civ_1_0139","shelter",2,"reg=civilian,family,worker,rescue|mood=sad",{1,"I think my daddy's still at the house, he won't leave it",2,"He'd never leave",1,"He said they'd have to carry him out",2,"I'd say that to a man with a shotgun, too"}},
{"fw_ld6_shelter_civ_1_0140","shelter",3,"reg=civilian,family,worker,rescue|mood=warm",{1,"I wrote down everybody's number in the front of my Bible",2,"When the lines come back",1,"When the lines come back, I'll have them, I'll start with Aunt Dot, she's the loudest",3,"She'll pick up on the first ring"}},
{"fw_ld6_shelter_civ_1_0141","shelter",2,"reg=civilian,family,worker,rescue",{1,"You wanna talk about it?",2,"No",1,"Okay",2,"...maybe later",1,"Yeah"}},
{"fw_ld6_shelter_civ_1_0142","shelter",3,"reg=civilian,family,worker,rescue|mood=sad",{1,"I never learned how to make her chicken and dumplings",2,"Why not?",1,"I always said I'd get the recipe, there was time",2,"She had a recipe card?",1,"It's in a tin in her kitchen, I know exactly which drawer",3,"Then you'll go get it"}},
{"fw_ld6_shelter_civ_1_0143","shelter",2,"reg=civilian,family,worker,rescue|day=7,10|mood=fear",{1,"I counted the days wrong, it's been nine, not eight",2,"Does it matter?",1,"It matters, I don't know why it matters, I just can't lose count of the days"}},
{"fw_ld6_shelter_civ_1_0144","shelter",3,"reg=civilian,family,worker,rescue|day=5,10|mood=sad",{1,"My boy's birthday was Tuesday",2,"I'm sorry",1,"I made him a card out of a cereal box, I was gonna mail it, there's no mail",2,"Keep it",3,"Give it to him when you see him"}},
{"fw_ld6_shelter_civ_1_0145","shelter",2,"reg=civilian,family,worker,rescue|mood=sad",{1,"I got my mother's ring in my pocket, I took it off her kitchen counter",2,"Why?",1,"Because she'd have wanted me to have it, and because I didn't want it left there"}},
{"fw_ld6_shelter_civ_1_0146","shelter",4,"reg=civilian,worker|mood=angry|world=door",{1,"You left the fucking door open all night!",2,"It was hot",1,"Anything could've walked in!",2,"Nothing did",1,"That's not the point",3,"It's a little bit the point"}},
{"fw_ld6_shelter_civ_1_0147","shelter",3,"reg=civilian,worker|mood=angry",{1,"That's my spot",2,"It's a floor",1,"It's the floor I picked, it's got the least dust",2,"There's no dust-free part of a floor, I'm moving over",1,"You're moving onto my jacket!",3,"Y'all are fighting over a jacket on a floor"}},
{"fw_ld6_shelter_civ_1_0148","shelter",3,"reg=civilian,family,worker,rescue|mood=funny|world=door",{1,"I'm not sleeping next to a Cardinals fan",2,"I don't even like basketball",1,"That's exactly what a Cardinals fan would say",3,"Put 'em by the door"}},
{"fw_ld6_shelter_civ_1_0149","shelter",4,"reg=civilian,family,worker,rescue|mood=angry",{1,"Preacher said it's a judgment",2,"On who",1,"On all of us",2,"Then God's got bad aim, my grandmother never hurt anybody",3,"Y'all want to do this now?",4,"Let 'em, it's something to do"}},
{"fw_ld6_shelter_civ_1_0150","shelter",3,"reg=civilian,worker|mood=angry",{1,"Don't touch my bag",2,"I wasn't touching it",1,"You had your hand on the strap",2,"The strap was in my way!",3,"It's a bag, it's got a lot of ways, and you're in all of them"}},
{"fw_ld6_shelter_civ_1_0151","shelter",3,"reg=civilian,worker|mood=funny",{1,"You narrate everything you do, you know that?",2,"I do not",1,"'Now I'm opening the can, now I'm sitting down'",2,"...I wasn't aware I was doing it",3,"Not aware, ladies and gentlemen"}},
{"fw_ld6_shelter_civ_1_0152","shelter",2,"reg=civilian,worker|mood=angry",{1,"You always leave one swallow in the bottle",2,"I used to. So?",1,"My brother did that. Handed back a bottle with one swallow instead of admitting he'd finished it",2,"He'd have called it manners",1,"I'd have called him a lazy ass"}},
{"fw_ld6_shelter_civ_1_0153","shelter",3,"reg=civilian,family,worker,rescue|mood=angry",{1,"You burnt it",2,"It's crispy",1,"It's goddamn charcoal",2,"Then you don't have to chew",3,"It's not even food, what was it"}},
{"fw_ld6_shelter_civ_1_0154","shelter",3,"reg=civilian,family,worker,rescue|day=2,6|mood=angry",{1,"We should go",2,"We're not going anywhere",1,"We've been sitting here for three days!",2,"And we're alive, and I'd like to stay that way",3,"Everybody pipe down, you'll bring the whole street"}},
{"fw_ld6_shelter_civ_1_0155","shelter",3,"reg=civilian,worker|mood=angry",{1,"Who made you boss",2,"Nobody",1,"Then why are you giving orders",2,"Because nobody else was, and somebody has to, so quit crying",3,"Quit crying, that's a point!"}},
{"fw_ld6_shelter_civ_1_0156","shelter",4,"reg=civilian,family,worker,rescue|mood=angry",{1,"That's not funny",2,"It's a little funny",1,"A man's dead and you're laughing",2,"It's the hat I'm laughing at",3,"What hat?",2,"He had a hat, a little feather in it, he'd wear it to the bank"}},
{"fw_ld6_shelter_civ_1_0157","shelter",2,"reg=civilian,family,worker,rescue|mood=angry",{1,"Don't touch the radio",2,"I'm just checking the dial",1,"Every time you check the dial it eats batteries",2,"It's a radio, it's supposed to eat batteries"}},
{"fw_ld6_shelter_civ_1_0158","shelter",3,"reg=civilian,family,worker,rescue|mood=angry",{1,"My mother always said, wash your hands",2,"Even when there wasn't much water?",1,"Especially then. She'd get upset if we'd forgotten to save any",2,"Hard choosing between that and drinking",3,"I know. Being told off was easier than having to make the choice"}},
{"fw_ld6_shelter_civ_1_0159","shelter",3,"reg=civilian,family,worker,rescue|mood=angry",{1,"I told you to check the back",2,"I checked the back",1,"It was unlocked",2,"I thought it was locked",1,"You THOUGHT?!",3,"Lord, here we go"}},
{"fw_ld6_shelter_civ_1_0160","shelter",3,"reg=civilian,family,worker,rescue|mood=grim",{1,"Every time you say when this is over",2,"What",1,"Stop saying it",2,"I'm just trying to-",1,"Stop",3,"Let it go, both of you"}},
{"fw_ld6_shelter_civ_1_0161","shelter",4,"reg=civilian,family,worker,rescue",{1,"Can we pray?",2,"Pray quietly",1,"I always pray quietly",2,"You pray like you're calling hogs",3,"Amen to that"}},
{"fw_ld6_shelter_civ_1_0162","shelter",2,"reg=civilian,family,worker,rescue|mood=angry",{1,"That jacket's mine",2,"It was on the floor",1,"It was on the floor because I put it on the floor, that's where I keep it",2,"I was cold",1,"It's ninety degrees!",2,"At night it was cold"}},
{"fw_ld6_shelter_civ_1_0163","shelter",2,"reg=civilian,worker|day=1,13|mood=angry",{1,"Nobody told us shit and nobody showed up, nobody ever said what to do",1,"And now I'm sitting in somebody's living room eating out of a can",2,"I know",1,"I pay taxes! I paid taxes Friday!",2,"They'll refund you"}},
{"fw_ld6_shelter_civ_1_0164","shelter",3,"reg=civilian,worker|mood=angry",{1,"The Army said stay inside, and then it left",2,"They didn't leave, they're regrouping",1,"They left, they put up a fucking line and they left",3,"You don't know that"}},
{"fw_ld6_shelter_civ_1_0165","shelter",3,"reg=civilian,family,worker,rescue|mood=funny",{1,"My boss called, said I'm late",2,"Did you tell him",1,"I told him I'd be in Monday, to the house, with a shotgun",3,"You did not",1,"I did not, I said sorry, I'll be in Monday"}},
{"fw_ld6_shelter_civ_1_0166","shelter",3,"reg=civilian,family,worker,rescue|mood=funny",{1,"Would anybody like to hear the weather?",2,"Go ahead",1,"Hot, with a chance of hot",3,"That's the best forecast I've heard all week"}},
{"fw_ld6_shelter_civ_1_0167","shelter",3,"reg=civilian,family,worker,rescue|mood=funny",{1,"No telemarketers, that's one good thing",2,"One",1,"Two, no jury duty, I already said that",3,"Three, nobody asks how my day was"}},
{"fw_ld6_shelter_civ_1_0168","shelter",2,"reg=civilian,family,worker,rescue|mood=funny",{1,"I'm writing a letter to the editor",2,"They shut the newspaper down",1,"Then it's a letter to nobody, so I can say whatever I want about the Army",2,"Read it to me"}},
{"fw_ld6_shelter_civ_1_0169","shelter",3,"reg=civilian,family,worker,rescue|mood=funny",{1,"My cousin's in the Guard and he couldn't find his own tent",2,"That's comforting",1,"I mean they're supposed to come get us",3,"Don't pin it on your cousin"}},
{"fw_ld6_shelter_civ_1_0170","shelter",2,"reg=civilian,family,worker,rescue|mood=funny",{1,"We've never been this clean and this filthy at the same time",2,"What does that mean",1,"I washed my face and my feet and I still feel dirty",2,"Wet isn't clean"}},
{"fw_ld6_shelter_civ_1_0171","shelter",2,"reg=civilian,family,worker,rescue|mood=funny",{1,"Hey, if I turn into one of them, don't let me eat the last can",2,"I'll save you a spoon",1,"That's all I ask"}},
{"fw_ld6_shelter_civ_1_0172","shelter",3,"reg=civilian,family,worker,rescue|mood=funny",{1,"I miss Monday",2,"You hate Monday",1,"I miss hating Monday, I'd hate it so good right now",3,"I'd go to the dentist, I'd get a root canal"}},
{"fw_ld6_shelter_civ_1_0173","shelter",3,"reg=civilian,family,worker,rescue|mood=funny",{1,"You two sound like an old married couple",2,"Mind your business",3,"It's right here, it's all out loud"}},
{"fw_ld6_shelter_civ_1_0174","shelter",3,"reg=civilian,family,worker,rescue|mood=funny",{1,"Swear to God that's what he said",2,"Who",1,"The guy at the hardware store",3,"Y'all been on that for twenty minutes",2,"It's a story, it takes a while"}},
{"fw_ld6_shelter_civ_1_0175","shelter",3,"reg=civilian,family,worker,rescue|mood=funny",{1,"You're lying",2,"I'm not",3,"Your eyebrow's doing that thing again"}},
{"fw_ld6_shelter_civ_1_0176","shelter",3,"reg=civilian,family,worker,rescue|mood=funny",{1,"It was three or four of them, maybe five",2,"It was two",1,"It FELT like five!",3,"It felt like a lot, every time somebody tells it"}},
{"fw_ld6_shelter_civ_1_0177","shelter",3,"reg=civilian,family,worker,rescue|mood=funny",{1,"Just kiss and make up already",2,"We're not fighting",3,"You've been quiet for an hour, that's a fight",2,"That's a nap"}},
{"fw_ld6_shelter_civ_1_0178","shelter",3,"reg=civilian,family,worker,rescue|mood=funny",{1,"I'm telling you, it's the best fish I ever caught",2,"How big",1,"This big, a good two feet",3,"That's three inches, I was there"}},
{"fw_ld6_shelter_civ_1_0179","shelter",3,"reg=civilian,family,worker,rescue|mood=funny",{1,"Keep it down, you're gonna wake the dead",2,"That's not funny",3,"It's a little funny",2,"Fine, a little"}},
{"fw_ld6_shelter_civ_1_0180","shelter",3,"reg=civilian,family,worker,rescue|mood=warm",{1,"You remember the song?",2,"Which one",1,"The one on the radio, the day, you know",3,"I remember, but I'm not singing it",1,"Nobody asked you to sing",3,"You were thinking it"}},
{"fw_ld6_shelter_civ_1_0181","shelter",4,"reg=civilian,family,worker,rescue|mood=funny",{1,"Who cut the cards",2,"You did",1,"I did not",3,"You both did, there's four cards on the floor",4,"I'm just here for the beans"}},
{"fw_ld6_shelter_civ_1_0182","shelter",3,"reg=civilian,family,worker,rescue|mood=funny|world=fence",{1,"I think I saw a deer",2,"A deer?",1,"Over by the old fence, plain as day",3,"It was a dog",1,"It was big, it was a deer",3,"It was a big dog"}},
{"fw_ld6_shelter_civ_1_0183","shelter",3,"reg=civilian,family,worker,rescue|mood=funny",{1,"And then he said, I'll take the whole case",2,"The whole case of what",1,"I never found out, he left",3,"You tell that story like it has an ending"}},
{"fw_ld6_shelter_civ_1_0184","shelter",3,"reg=civilian,worker|mood=funny",{1,"You eat like a goddamn animal",2,"You chew like one",3,"You both eat like animals, and I'm sitting right here"}},
{"fw_ld6_shelter_civ_1_0185","shelter",3,"reg=civilian,family,worker,rescue|mood=funny",{1,"I told her, I said, you can't park there",2,"What'd she say",1,"She said watch me",3,"And that's why she's not here anymore"}},
{"fw_ld6_shelter_civ_1_0186","shelter",3,"reg=civilian,family,worker,rescue|mood=warm",{1,"Go on, deny it. You're smiling",2,"I'm not",3,"You're a little bit smiling",2,"It's gas, don't flatter yourself"}},
{"fw_ld6_shelter_civ_1_0187","shelter",4,"reg=civilian,family,worker,rescue|mood=funny|world=building",{1,"Somebody get me a beer",2,"We don't have beer",1,"Then get me something that used to be near beer",3,"There's a jar of pickled eggs in the pantry",1,"That's a start"}},
{"fw_ld6_shelter_civ_1_0188","shelter",3,"reg=civilian,family,worker,rescue|mood=warm",{1,"You hear that?",2,"What",1,"Somebody's laughing, over there",3,"About time, honestly"}},
{"fw_ld6_shelter_civ_2_0001","shelter",3,"reg=civilian,family,worker,rescue|mood=calm",{1,"Nothing out here",2,"Nothing's good",1,"Same nothing as an hour ago",3,"Then it's holding"}},
{"fw_ld6_shelter_civ_2_0002","shelter",3,"reg=civilian,family,worker,rescue|mood=calm",{1,"Dog's barking again, way off",2,"How far?",1,"Far, I can barely hear it, it's not coming this way",2,"Tell me when it is",3,"I'll tell you, I'm not sleeping anyway..."}},
{"fw_ld6_shelter_civ_2_0003","shelter",4,"reg=civilian,family,worker,rescue|mood=calm",{1,"Counted forty-one crows so far",2,"Why are you counting crows",1,"It's that or fall asleep standing up",3,"Forty-two, one just landed",4,"That one's mine, I named it"}},
{"fw_ld6_shelter_civ_2_0004","shelter",3,"reg=civilian,family,worker,rescue",{1,"What's the worst trade you ever offered?",2,"Trade for what?",1,"Offered a chair and my last cigarette to get out of a shift",2,"What kind of chair?",1,"Three legs. But it did come with a cigarette",3,"I'd have told you to keep it. You'd have looked miserable enough already"}},
{"fw_ld6_shelter_civ_2_0005","shelter",4,"reg=civilian,family,worker,rescue|mood=fear",{1,"Shh, hold on",2,"What",1,"Listen",2,"I don't hear any--",1,"...nothing, never mind, my ears are doing it again",3,"Mine too, it's that ringing"}},
{"fw_ld6_shelter_civ_2_0006","shelter",4,"reg=civilian,family,worker,rescue",{1,"Two hours, who's up after me",2,"I'll take it",1,"You said that yesterday and then you slept through it",2,"I'll take it for real",3,"I'll take it, nobody's waking that one up",4,"I'll take whatever's left"}},
{"fw_ld6_shelter_civ_2_0007","shelter",3,"reg=civilian,family,worker,rescue|mood=calm",{1,"Quiet as a church out here",2,"That's what bothers me",1,"Church bothers you?",2,"Church on Sunday, quiet like that, and then somebody coughs",3,"Somebody always coughs"}},
{"fw_ld6_shelter_civ_2_0008","shelter",3,"reg=civilian,family,worker,rescue|mood=funny",{1,"Water over here, please",2,"You've got a canteen",1,"It's empty and I'm up here dying",2,"Dying, right, you've been up there ten minutes",3,"Bring the water up, you're gonna fall over"}},
{"fw_ld6_shelter_civ_2_0009","shelter",4,"reg=civilian,family,worker,rescue",{1,"Movement, left side",2,"Where",1,"It's a cat, never mind, it's just a cat",3,"It's always a cat",2,"Until it's not a cat",4,"Hush, let 'em watch"}},
{"fw_ld6_shelter_civ_2_0010","shelter",3,"reg=civilian,family,worker,rescue|mood=funny",{1,"My eyes are doing that thing where everything moves",2,"That's tired",1,"It's moving a lot",2,"Sit down, I'll take it",3,"Sit down before you fall down"}},
{"fw_ld6_shelter_civ_2_0011","shelter",3,"reg=civilian,family,worker,rescue|world=window",{1,"I think the neighbor's light is on",2,"Which neighbor",1,"The one across, second window, it wasn't on before",2,"Is it flickering?",1,"No, steady, it's just on",3,"That's a person"}},
{"fw_ld6_shelter_civ_2_0012","shelter",3,"reg=civilian,family,worker,rescue",{1,"Somebody's chimney's going, you can see the line",2,"Whose",1,"I don't know, a few houses down",2,"Then we're not the only ones",1,"No, we're not",3,"Don't wave"}},
{"fw_ld6_shelter_civ_2_0013","shelter",3,"reg=civilian,family,worker,rescue|mood=sad",{1,"You okay up there",2,"Yeah",1,"You've been quiet",2,"I'm watching",1,"You're not watching, you're thinking",2,"...both",3,"Leave the post a minute, I've got it"}},
{"fw_ld6_shelter_civ_2_0014","shelter",3,"reg=civilian,family,worker,rescue|world=door",{1,"Can I ask a stupid question",2,"Go on",1,"If one of them comes up to the door, I mean really close, do I wake everybody or just you",2,"Just me, then me and the baseball bat will see",3,"Wake me too, I like a show"}},
{"fw_ld6_shelter_civ_2_0015","shelter",4,"reg=civilian,family,worker,rescue",{1,"Half hour left on my shift",2,"It's been a half hour for an hour",1,"It's been twenty minutes, I've been counting",3,"Twenty minutes, and we've all heard about it",4,"Somebody give 'em a watch"}},
{"fw_ld6_shelter_civ_2_0016","shelter",3,"reg=civilian,family,worker,rescue|hour=4,9|mood=calm|world=summer",{1,"Sun's coming up, kinda orange",2,"Is it going to be hot",1,"It's already hot, it was hot at midnight",3,"It's summer, hot's the weather"}},
{"fw_ld6_shelter_civ_2_0017","shelter",3,"reg=civilian,family,worker,rescue|mood=sad",{1,"You eat yet?",2,"Not hungry",1,"You didn't eat yesterday either",2,"I said I'm not hungry",3,"Leave the can next to them"}},
{"fw_ld6_shelter_civ_2_0018","shelter",3,"reg=civilian,family,worker,rescue|day=1,13",{1,"You've said maybe ten words today",2,"Eleven",1,"Smartass",2,"Twelve",3,"That's the most you've said since Friday"}},
{"fw_ld6_shelter_civ_2_0019","shelter",3,"reg=civilian,family,worker,rescue|mood=sad",{1,"Where do you keep going?",2,"Nowhere",1,"You get up and walk to the end of the room and sit back down",2,"I'm stretching",1,"For an hour?",3,"Let it be"}},
{"fw_ld6_shelter_civ_2_0020","shelter",3,"reg=civilian,family,worker,rescue|mood=warm",{1,"You mind if I sit here?",2,"No",1,"I won't talk",2,"Okay",1,"...thanks",3,"That's the nicest conversation I've heard in days"}},
{"fw_ld6_shelter_civ_2_0021","shelter",3,"reg=civilian,family,worker,rescue",{1,"How are your hands?",2,"Fine...",1,"They're shaking",2,"It's the coffee",1,"We don't have coffee",2,"Then it's something else",3,"Give 'em a minute"}},
{"fw_ld6_shelter_civ_2_0022","shelter",3,"reg=civilian,family,worker,rescue|mood=sad|world=building",{1,"What's wrong?",2,"Nothing",1,"It's not nothing, you've been staring at that wall all day",2,"Leave it",1,"Okay",3,"Leave 'em, they'll talk when they talk"}},
{"fw_ld6_shelter_civ_2_0023","shelter",4,"reg=civilian,family,worker,rescue|day=2,6",{1,"You said you were gonna tell me what happened",2,"Later",1,"Later's been three days",2,"Then it's still later",3,"Let it go, you're gonna scratch it raw"}},
{"fw_ld6_shelter_civ_2_0024","shelter",3,"reg=civilian,family,worker,rescue|mood=warm",{1,"Somebody once gave me a button",2,"What?",1,"Found it on the floor. Said it was a nice button",2,"Was it?",1,"It was to them. They wanted me to have something",3,"That's the sweetest thing I've heard all week"}},
{"fw_ld6_shelter_civ_2_0025","shelter",4,"reg=civilian,family,worker,rescue|mood=calm",{1,"Don't talk to 'em, they're thinking",2,"About what",1,"I don't know, that's why I'm not talking",3,"That's rude",4,"Polite is leaving thinking people alone"}},
{"fw_ld6_shelter_civ_2_0026","shelter",4,"reg=civilian,family,worker,rescue",{1,"You gonna sit in that corner all day?",2,"Probably...",1,"Why that corner",2,"It's got two walls, and nobody comes at me from behind",3,"That's fair"}},
{"fw_ld6_shelter_civ_2_0027","shelter",4,"reg=civilian,family,worker,rescue|mood=calm",{1,"I'm not even here",2,"You're right there",1,"I'm not here, I'm reading",2,"You've been on that page for an hour",1,"It's a good page",3,"What's it say"}},
{"fw_ld6_shelter_civ_2_0028","shelter",4,"reg=civilian,family,worker,rescue",{1,"I used to fight my brother for the corner seat",2,"Whole room to sit in?",1,"Had the best draft",2,"We'd argue about a draft neither of us could feel",3,"Then Mama would tell us to share. Plenty of space, two fools"}},
